import numpy as np
from scipy import ndimage
from collections import deque

def solve(inp):
    a = np.array(inp)
    H, W = a.shape
    lab, n = ndimage.label(a==1, structure=np.ones((3,3)))
    # closed test: component is a closed cycle <=> every cell has deg>=2 and it forms single cycle
    closed = np.zeros(n+1, bool)
    for i in range(1, n+1):
        cells = set(map(tuple, np.argwhere(lab==i).tolist()))
        ok = all(sum(((r+dr,c+dc) in cells) for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]) == 2 for (r,c) in cells)
        if ok and cells:
            # verify single cycle
            start = next(iter(cells)); seen={start}; st=[start]
            while st:
                r,c = st.pop()
                for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                    q=(r+dr,c+dc)
                    if q in cells and q not in seen: seen.add(q); st.append(q)
            closed[i] = (seen == cells)
    wall = np.zeros((H,W), bool)
    for i in range(1, n+1):
        if closed[i]: wall |= (lab==i)
    # flood fill 0-cells from border (4-conn) avoiding walls
    out = a.copy()
    reach = np.zeros((H,W), bool)
    dq = deque()
    for r in range(H):
        for c in (0, W-1):
            if a[r,c]==0 and not wall[r,c] and not reach[r,c]: reach[r,c]=True; dq.append((r,c))
    for c in range(W):
        for r in (0, H-1):
            if a[r,c]==0 and not wall[r,c] and not reach[r,c]: reach[r,c]=True; dq.append((r,c))
    while dq:
        r,c = dq.popleft()
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            r2,c2 = r+dr, c+dc
            if 0<=r2<H and 0<=c2<W and a[r2,c2]==0 and not wall[r2,c2] and not reach[r2,c2]:
                reach[r2,c2]=True; dq.append((r2,c2))
    # dilate closed comps by 1 (8-conn)
    for i in range(1, n+1):
        if not closed[i]: continue
        comp = (lab==i)
        dil = ndimage.binary_dilation(comp, structure=np.ones((3,3)))
        for r,c in map(tuple, np.argwhere(dil & (a==0)).tolist()):
            out[r,c] = 3 if not reach[r,c] else 2
    return out

